import{_ as o,a as s,b as p}from"./chunks/PageInfo.vue_vue_type_script_setup_true_lang.BCVHfIj7.js";import{_ as l,c as n,I as e,a7 as i,o as T}from"./chunks/framework.DGCt2JJv.js";import"./chunks/dayjs.min.DZyl58SH.js";const _="/long-press/assets/80d2173b.ufc8esDH.png",c="/long-press/assets/5ee71ed0.lFAGrQSw.png",d="/long-press/assets/c86d77ce.DIAkwt7-.png",h="/long-press/assets/f1f20e35.BIEc4ZTo.png",q=JSON.parse('{"title":"解决实际项目中stalled时间过久的问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/解决实际项目中stalled时间过久的问题.md","filePath":"guide/解决实际项目中stalled时间过久的问题.md","lastUpdated":1722001547000}'),m={name:"guide/解决实际项目中stalled时间过久的问题.md"},P=i('<h1 id="解决实际项目中stalled时间过久的问题" tabindex="-1">解决实际项目中stalled时间过久的问题 <a class="header-anchor" href="#解决实际项目中stalled时间过久的问题" aria-label="Permalink to &quot;解决实际项目中stalled时间过久的问题&quot;">​</a></h1><p><a href="https://blog.csdn.net/luxinfeng666/article/details/129106187" target="_blank" rel="noreferrer">https://blog.csdn.net/luxinfeng666/article/details/129106187</a></p><h2 id="问题排查" tabindex="-1">问题排查 <a class="header-anchor" href="#问题排查" aria-label="Permalink to &quot;问题排查&quot;">​</a></h2><p>页面加载速度太慢，严重影响了用户体验，因此必须要解决这个问题。</p><p>开始的时候怀疑是后端接口问题，因此针对一些计算量确实很大的接口，对热点数据加了缓存。</p><p>理论上来说，加了缓存后接口速度应该在100ms以内就可以返回，但是实际在页面上查看接口返回时间时，发现接口的返回时间有时还是会到3秒左右，这种情况就存在问题了。</p><p>针对单一接口，我使用postman发起调用，发现无法复现该问题，只有在前端页面上请求才会存在返回时间超过3秒的情况。</p><p>因此，我们开始使用Chrome浏览器提供的工具查看这些耗时较多的接口。 <img src="'+_+'" alt=""> 从该页面中选取了一个接口进行测试，点击Chrome浏览器的调试按钮，查看网络面板中的时间数据，整个接口的耗时如上图所示。</p><p>简单解释一下：该接口整体的响应时间为281.47ms，其中Stalled时间占用了169.84ms的时间，获取后端接口数据的时间为111.63ms。</p><p>其中，111.63ms可以理解为后端接口的真实响应时间，但是stalled的这段时间是干什么的呢？这一阶段的耗时比后端接口返回数据的时间还要长。</p><p>对Chrome发起的网络请求进行抓包，具体操作如下： <img src="'+c+'" alt=""></p><ol><li>进入chrome://net-export/网页点击开始调试</li><li>重新请求该报表页面</li><li>停止抓包，保存日志文件</li><li>进入<a href="https://netlog-viewer.appspot.com/#import%E7%BD%91%E9%A1%B5%EF%BC%8C%E5%AF%BC%E5%85%A5%E6%8A%93%E5%8C%85%E6%97%A5%E5%BF%97%EF%BC%8C%E5%AF%B9%E6%8A%93%E5%8C%85%E6%97%A5%E5%BF%97%E8%BF%9B%E8%A1%8C%E5%8F%AF%E8%A7%86%E5%8C%96%E5%88%86%E6%9E%90%EF%BC%8C%E7%BB%93%E6%9E%9C%E5%A6%82%E4%B8%8B%E5%9B%BE%E6%89%80%E7%A4%BA" target="_blank" rel="noreferrer">https://netlog-viewer.appspot.com/#import网页，导入抓包日志，对抓包日志进行可视化分析，结果如下图所示</a><img src="'+d+'" alt=""></li></ol><p>点击最上侧的搜索框，可以按照接口URL进行搜索，搜索排查后发现接口是在 <code>HTTP_STREAM_REQUEST_BOUND_TO_JOB</code>阶段耗时过多，再进一步查看，发现是接口在等待复用套接字。</p><p>到这里，我们就知道为什么前端页面上的接口相应时间过长了，主要时间都耗费在等待复用套接字上了，那为什么会在这个地方进行等待呢，</p><p>是因为HTTP1.1限制了在Chrome浏览器下对同一个域名的并发请求最大是6，当超过6个时，就得排队等待前面的请求数据返回释放套接字后才能进行请求。</p><h2 id="问题解决" tabindex="-1">问题解决 <a class="header-anchor" href="#问题解决" aria-label="Permalink to &quot;问题解决&quot;">​</a></h2><p>查明了问题，那如何解决这个问题呢？</p><p>两个办法：一个是由于HTTP1.1是对单个域名限制了并发请求数，那我们可以同时对多个域名进行请求来避免阻塞；</p><p>另一个是升级HTTP协议，将HTTP协议升级到HTTP2.0，HTTP2.0由于多路复用的特性，不再限制并发请求数</p><p>（需注意对后端系统的负载影响，同时并发请求会对后端系统造成更大的负载，还需注意客户端对HTTP2.0协议的兼容性，如果不兼容的话，即使开启了HTTP2.0，也会退化到HTTP1.1的）。</p><p>综合多种考虑，结合公司里关于HTTP2.0的故障反馈，确认对我们的系统无影响后，决定升级HTTP协议来解决该问题，先在测试环境开启，测试几天后，在线上环境灰度开启，最终全部开启。</p><blockquote><p>注意，HTTP2.0协议强依赖于HTTPS协议，需确保服务首先支持HTTPS协议！</p></blockquote><h2 id="http1-1存在的问题" tabindex="-1">HTTP1.1存在的问题 <a class="header-anchor" href="#http1-1存在的问题" aria-label="Permalink to &quot;HTTP1.1存在的问题&quot;">​</a></h2><p>HTTP2.0出现，肯定是为了解决前代HTTP存在的问题。在之前的HTTP协议中，主要存在连接无法复用、连接并发数限制等。</p><p>由于HTTP是基于TCP协议，因此在新建HTTP链接时，都会经历三次握手和慢启动，当延迟较高时，对相应速度的影响会更明显些。如果能实现链接复用，则可以极大程度降低这些的影响。</p><p>当前Chrome浏览器限制对同一个域名最大6个并发请求，当超过6个时，会阻塞后面的请求，严重拉低整个页面的加载速度（当前许多网站为了避开这个影响，会使用多个域名的CDN，也是因为这个限制）。</p><h2 id="http2-0的优势" tabindex="-1">HTTP2.0的优势 <a class="header-anchor" href="#http2-0的优势" aria-label="Permalink to &quot;HTTP2.0的优势&quot;">​</a></h2><p>多路复用</p><p>HTTP2.0中的一大亮点就是多路复用，即允许同时通过单一的HTTP2.0连接发起多重的请求-响应消息，这样就解决了HTTP1.1中并发数的限制。</p><p>那为什么1.1不能实现多路复用呢？是因为HTTP2.0使用了不同的传输格式。</p><p>二进制分帧</p><p>在HTTP1.1和1.0时代，传输的是明文协议，其格式由三部分组成：start line, header 和body，整体解析是基于文本的。</p><p>但是在HTTP2.0中，不再基于文本，而是将一个请求分割成多个二进制帧，结构如下 <img src="'+h+'" alt=""> 我们可以通过stream ID区分这个二进制帧是哪个请求的，同时，在传输时，帧与帧时间也没有严格的顺序要求，等传输到目标端口后再进行合并即可。</p><p>此外，在HTTP2.0中，还可以针对每个stream设置优先级和依赖，优先级高的会被server优先处理。</p><p>首部压缩</p><p>在HTTP1.1中，每次请求都需要发送整个请求头，但是多次发送的请求头中许多信息都没有变化，这样就造成了带宽浪费。</p><p>在HTTP2.0中，通讯双方各自缓存一份header fields表，这样既避免了重复header的传输，减少了发送包的数量从而降低了延迟。</p><h2 id="contributors" tabindex="-1">Contributors <a class="header-anchor" href="#contributors" aria-label="Permalink to &quot;Contributors&quot;">​</a></h2>',38);function E(H,u,f,b,g,C){const t=o,a=s,r=p;return T(),n("div",null,[P,e(t,{readTime:"4",words:"1.5k"}),e(a),e(r)])}const x=l(m,[["render",E]]);export{q as __pageData,x as default};
